ch($fee_masters as $g){ ?><tr><td><strong><?php echo html_escape($g->group_name); ?></strong></td><td><?php foreach($g->feetypes as $f){ ?><div style="padding:5px 0;border-bottom:1px solid #edf1f5"><?php echo html_escape($f->type); ?><span class="pull-right"><?php echo number_format($f->amount,2); ?></span></div><?php } ?></td></tr><?php } ?></tbody></table></div></div></section>

