} ?></select></div><div><label class="fw-label">Section</label><select class="form-control" id="fw-discount-section"><option value="">All sections</option></select></div><button type="button" class="fw-btn fw-btn-primary" id="fw-load-discount-students"><i class="fa fa-users"></i> Load Students</button></div><div id="fw-discount-students" class="fw-empty">Choose a class to assign this discount.</div></div></section>

<section class="fw-setup-pane" data-pane="transfer"><h4><i class="fa fa-exchange"></i> Previous Session Balance</h4><p class="text-muted">Review calculated unpaid balances before transferring them into <?php echo html_escape($session_name); ?>.</p><div class="fw-toolbar" style="grid-template-columns:1fr 1fr 1fr auto"><div><label class="fw-label">Class</label><select class="form-control" id="fw-transfer-class"><option value="">Select class</option><?php foreach($this->class_model->get() as $c){ ?><option value="<?php echo (int)$c['id']; ?>"><?php echo html_escape($c['class']); ?></option><?php } ?></select></div><div><label class="fw-label">Section</label><select class="form-control" id="fw-transfer-section"><option value="">Select section</option></select></div><div><label class="fw-label">Due Date</label><input class="form-control" type="date" id="fw-transfer-date" value="<?php echo date('Y-m-d'); ?>"></div><button type="button" class="fw-btn fw-btn-primary" id="fw-load-balances"><i class="fa fa-calculator"></i> Review Balances</button></div><div id="fw-balance-results" class="fw-empty">Select a class and section to calculate previous-session balances.</div></section>
