<script>(function($){var initial='<?php echo html_escape($tab); ?>';function show(t){$('.fw-setup-pane').hide().filter('[data-pane="'+t+'"]').show();$('#fw-setup-tabs a').removeClass('active').filter('[data-tab="'+t+'"]').addClass('active');}$('#fw-setup-tabs a[data-tab]').on('click',function(e){e.preventDefault();show($(this).data('tab'));history.replaceState(null,'','?tab='+$(this).data('tab'));});show(initial);})(jQuery);</script>
<script>(function($){function esc(v){return $('<div>').text(v==null?'':v).html()}function sections(classBox,sectionBox,all){$(classBox).on('change',function(){var s=$(sectionBox).html('<option value="">'+(all?'All sections':'Select section')+'</option>');if(!this.value)return;$.getJSON('<?php echo site_url('sections/getByClass'); ?>',{class_id:this.value},function(a){$.each(a,function(_,x){s.append($('<option>').val(x.section_id||x.id).text(x.section))})})})}function lock(b,on,label){if(on)b.prop('disabled',true).data('old',b.html()).html('<i class="fa fa-spinner fa-spin"></i> '+label);else b.prop('disabled',false).html(b.data('old'))}
sections('#fw-discount-class','#fw-discount-section',true);sections('#fw-transfer-class','#fw-transfer-section',false);
$('.fw-assign-discount').on('click',function(){$('#fw-discount-id').val($(this).data('id'));$('#fw-discount-name').text($(this).data('name'));$('#fw-discount-assignment').show();$('#fw-discount-students').html('<div class="fw-empty">Choose a class to assign this discount.</div>');$('html,body').animate({scrollTop:$('#fw-discount-assignment').offset().top-80},250)});
$('#fw-load-discount-students').on('click',function(){var b=$(this),cid=$('#fw-discount-class').val();if(!cid)return;lock(b,1,'Loading');$.post('<?php echo site_url('admin/feeworkspace/discountStudents'); ?>',{discount_id:$('#fw-discount-id').val(),class_id:cid,section_id:$('#fw-discount-section').val()},function(r){var h='<div style="margin:12px 0"><label><input type="checkbox" id="fw-discount-all"> Select all</label> <span class="fw-pill" id="fw-discount-count">0 selected</span></div><div class="table-responsive"><table class="table fw-table"><thead><tr><th></th><th>Admission</th><th>Student</th><th>Class</th></tr></thead><tbody>';$.each(r.students,function(_,x){var checked=Number(x.student_fees_discount_id)>0?' checked':'';h+='<tr><td><input class="fw-discount-check" type="checkbox" value="'+x.student_session_id+'"'+checked+'></td><td>'+esc(x.admission_no)+'</td><td>'+esc([x.firstname,x.middlename,x.lastname].filter(Boolean).join(' '))+'</td><td>'+esc(x.class+' / '+x.section)+'</td></tr>'});h+='</tbody></table></div><button type="button" class="fw-btn fw-btn-success" id="fw-save-discount"><i class="fa fa-save"></i> Save Assignments</button> <span id="fw-discount-message"></span>';$('#fw-discount-students').html(h);countDiscount()},'json').fail(function(x){$('#fw-discount-students').html('<div class="alert alert-danger">'+esc(x.responseJSON?x.responseJSON.message:'Unable to load students.')+'</div>')}).always(function(){lock(b,0)})});
$(document).on('change','#fw-discount-all',function(){$('.fw-discount-check').prop('checked',this.checked);countDiscount()}).on('change','.fw-discount-check',countDiscount);function countDiscount(){$('#fw-discount-count').text($('.fw-discount-check:checked').length+' selected')}
$(document).on('click','#fw-save-discount',function(){var b=$(this),ids=$('.fw-discount-check:checked').map(function(){return this.value}).get();lock(b,1,'Saving');$.post('<?php echo site_url('admin/feeworkspace/saveDiscountStudents'); ?>',{discount_id:$('#fw-discount-id').val(),class_id:$('#fw-discount-class').val(),section_id:$('#fw-discount-section').val(),student_session_ids:ids},function(r){$('#fw-discount-message').attr('class','text-success').text(r.message)},'json').fail(function(x){$('#fw-discount-message').attr('class','text-danger').text(x.responseJSON?x.responseJSON.message:'Save failed.')}).always(function(){lock(b,0)})});
$('#fw-load-balances').on('click',function(){var b=$(this),cid=$('#fw-transfer-class').val(),sid=$('#fw-transfer-section').val();if(!cid||!sid)return;lock(b,1,'Calculating');$.post('<?php echo site_url('admin/feeworkspace/previousBalances'); ?>',{class_id:cid,section_id:sid},function(r){var h='<div class="fw-note" style="margin:14px 0">Source session: '+esc(r.previous_session)+(r.is_update?' · Existing transferred values are shown and can be updated.':' · Balances calculated from assigned fees minus payments and discounts.')+'</div><div><label><input type="checkbox" id="fw-balance-all" checked> Select all</label> <span class="fw-pill" id="fw-balance-count"></span></div><div class="table-responsive"><table class="table fw-table"><thead><tr><th></th><th>Admission</th><th>Student</th><th>Father</th><th class="text-right">Balance</th></tr></thead><tbody>';$.each(r.students,function(_,x){h+='<tr><td><input type="checkbox" class="fw-balance-check" value="'+x.student_session_id+'" checked></td><td>'+esc(x.admission_no)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.father_name)+'</td><td><input class="form-control fw-balance-amount text-right" data-id="'+x.student_session_id+'" type="number" min="0" step="0.01" value="'+Number(x.balance).toFixed(2)+'"></td></tr>'});h+='</tbody></table></div><button type="button" class="fw-btn fw-btn-success" id="fw-save-balances"><i class="fa fa-exchange"></i> Transfer Selected Balances</button> <span id="fw-balance-message"></span>';$('#fw-balance-results').html(h);countBalances()},'json').fail(function(x){$('#fw-balance-results').html('<div class="alert alert-danger">'+esc(x.responseJSON?x.responseJSON.message:'Unable to calculate balances.')+'</div>')}).always(function(){lock(b,0)})});
$(document).on('change','#fw-balance-all',function(){$('.fw-balance-check').prop('checked',this.checked);countBalances()}).on('change','.fw-balance-check',countBalances);function countBalances(){$('#fw-balance-count').text($('.fw-balance-check:checked').length+' selected')}
$(document).on('click','#fw-save-balances',function(){if(!confirm('Transfer the selected reviewed balances into the current session?'))return;var b=$(this),amounts={};$('.fw-balance-check:checked').each(function(){amounts[this.value]=$('.fw-balance-amount[data-id="'+this.value+'"]').val()});lock(b,1,'Transferring');$.post('<?php echo site_url('admin/feeworkspace/savePreviousBalances'); ?>',{class_id:$('#fw-transfer-class').val(),section_id:$('#fw-transfer-section').val(),due_date:$('#fw-transfer-date').val(),amounts:amounts},function(r){$('#fw-balance-message').attr('class','text-success').text(r.message)},'json').fail(function(x){$('#fw-balance-message').attr('class','text-danger').text(x.responseJSON?x.responseJSON.message:'Transfer failed.')}).always(function(){lock(b,0)})});
})(jQuery);</script>
